	/*
     * @param	event CreateTradeEvent
     */
    @EventHandler( payloadType=CreateTradeEvent.class )
    public void handle( CreateTradeEvent event) {
	    LOGGER.info("handling CreateTradeEvent - " + event );
	    Trade entity = new Trade();
            entity.setTradeId( event.getTradeId() );
            entity.setExecutedAt( event.getExecutedAt() );
            entity.setQuantity( event.getQuantity() );
            entity.setPrice( event.getPrice() );
            entity.setFees( event.getFees() );
            entity.setSettlementDate( event.getSettlementDate() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllTrade( entity );
    }

    /*
     * @param	event UpdateTradeEvent
     */
    @EventHandler( payloadType=UpdateTradeEvent.class )
    public void handle( UpdateTradeEvent event) {
    	LOGGER.info("handling UpdateTradeEvent - " + event );
    	
	    Trade entity = new Trade();
            entity.setTradeId( event.getTradeId() );
            entity.setExecutedAt( event.getExecutedAt() );
            entity.setQuantity( event.getQuantity() );
            entity.setPrice( event.getPrice() );
            entity.setFees( event.getFees() );
            entity.setSettlementDate( event.getSettlementDate() );
            entity.setOrder( event.getOrder() );
            entity.setSecurity( event.getSecurity() );
            entity.setInvestmentAccount( event.getInvestmentAccount() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindTrade( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllTrade( entity );        
    }
    
