    /**
     * Method to retrieve the Trade via an TradePrimaryKey.
     * @param 	id Long
     * @return 	Trade
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Trade handle( FindTradeQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getTradeId() );
    }
    
    /**
     * Method to retrieve a collection of all Trades
     *
     * @param	query	FindAllTradeQuery 
     * @return 	List<Trade> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Trade> handle( FindAllTradeQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindTrade,
 * but only if the id matches
 *
 * @param		entity	Trade
 */
	protected void emitFindTrade( Trade entity ) {
		LOGGER.info("handling emitFindTrade" );
		
	    queryUpdateEmitter.emit(FindTradeQuery.class,
	                            query -> query.getFilter().getTradeId().equals(entity.getTradeId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllTrade
	 * 
	 * @param		entity	Trade
	 */
	protected void emitFindAllTrade( Trade entity ) {
		LOGGER.info("handling emitFindAllTrade" );
		
	    queryUpdateEmitter.emit(FindAllTradeQuery.class,
	                            query -> true,
	                            entity);
	}

